text:
.fx { font-family: var(--font-sans); color: var(--color-fg); padding: var(--dash-pad-lg); display: grid; gap: var(--dash-gap-lg); }
.fx-title { font-family: var(--font-serif); font-size: var(--dash-font-size-title); margin: 0; }
.fx-lede { font-size: var(--dash-font-size-body); color: var(--color-fg-muted); }
.fx-filters { display: flex; gap: var(--dash-gap-md); align-items: center; flex-wrap: wrap; }
.fx-clear { border: 1px solid var(--color-border-line); background: var(--color-panel); color: var(--color-fg); border-radius: var(--dash-radius); padding: 4px 10px; }
.fx-tabs { display: flex; gap: var(--dash-gap-sm); border-bottom: 1px solid var(--color-border-line); }
.fx-tabs button { background: none; border: 0; padding: 8px 12px; color: var(--color-fg-muted); }
.fx-tabs button[aria-selected="true"] { color: var(--color-fg); border-bottom: 2px solid var(--dash-chart-1); }
.fx-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: var(--dash-gap-md); }
.fx-card { background: var(--color-panel); border: 1px solid var(--color-border-line); border-radius: var(--dash-radius); padding: var(--dash-pad-md); }
.fx-card h2 { font-size: var(--dash-font-size-heading); margin: 0; }
.fx-big { font-size: var(--dash-font-size-title); margin: 4px 0; font-variant-numeric: tabular-nums; }
.fx-note { font-size: var(--dash-font-size-caption); color: var(--color-fg-muted); }
.fx-chart { margin: 0; }
.fx-chart figcaption { font-size: var(--dash-font-size-heading); margin-bottom: var(--dash-gap-sm); }
.fx-chart-body { position: relative; min-height: 220px; }
.fx-tip { position: absolute; pointer-events: none; background: var(--dash-surface-popover); border: 1px solid var(--dash-border); box-shadow: var(--dash-shadow-popover); border-radius: var(--dash-radius); padding: 4px 8px; font-size: var(--dash-font-size-caption); }
.fx-table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
.fx-table th, .fx-table td { text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--color-border-line); }
.fx-list { padding-left: 1.2em; }
[data-dash-source-state="refreshing"] { opacity: 0.6; }
[data-dash-source-state="error"] { color: var(--color-bad); }
